   "orig": "Brett Crawford faces tactical puzzle as Mr Incredible begins Classic Mile quest at Sha Tin",
   "lead": "L'allenatore Brett Crawford punta molto sul giovane cavallo Mr Incredible, che torna in pista lunedì a Sha Tin, a Hong Kong, nella Lek Yuen Handicap di Classe Tre sui 1.200 metri, primo passo verso la Classic Mile. Il compito non sarà semplice: il cavallo partirà dallo stallo 11. Figlio di Toronado, aveva impressionato la scorsa stagione vincendo all'esordio a marzo, perdendo un mese dopo con attenuanti e poi imponendosi con tre lunghezze di vantaggio. Lo riferisce South China Morning Post.",
